<?php $latestOpportunityEvent=null;foreach($events as $candidate){if($candidate['voided_at']===null){$latestOpportunityEvent=$candidate;break;}}?><?php if($latestOpportunityEvent&&$latestOpportunityEvent['from_stage']!==null):?><section class="settings-panel"><h2>Correct latest stage</h2><p>Voiding this transition restores the preceding stage and keeps a visible audit trail.</p><form method="post" action="<?= $escape($router->url('opportunities.events.void',['id'=>$opportunity['id'],'eventId'=>$latestOpportunityEvent['id']])) ?>"><input type="hidden" name="_csrf" value="<?= $escape($csrfToken) ?>"><input type="hidden" name="version" value="<?= $escape($opportunity['version']) ?>"><input type="hidden" name="event_version" value="<?= $escape($latestOpportunityEvent['version']) ?>"><label>Correction reason<input name="void_reason" required></label><button>Void latest stage event</button></form></section><?php endif;?>
<header class="page-header"><div><p class="eyebrow"><?= $escape($stages[$opportunity['stage']]??$opportunity['stage']) ?></p><h1><?= $escape($opportunity['company_name']?:$opportunity['contact_name']) ?></h1><p><?= $escape($offers[$opportunity['offer_key']]??$opportunity['offer_key']) ?> · $<?= $escape($opportunity['value_amount']) ?></p></div><a class="button" href="<?= $escape($editUrl) ?>">Edit</a></header><?php if(!in_array($opportunity['stage'],['won','lost'],true)):?><section><h2>Commercial details</h2><form method="post" action="<?= $escape($updateUrl) ?>"><input type="hidden" name="_csrf" value="<?= $escape($csrfToken) ?>"><input type="hidden" name="version" value="<?= $escape($opportunity['version']) ?>"><label>Offer<select name="offer_key"><?php foreach($offers as $key=>$label):?><option value="<?= $escape($key) ?>"<?= $key===$opportunity['offer_key']?' selected':'' ?>><?= $escape($label) ?></option><?php endforeach;?></select></label><label>Estimated value (USD)<input name="value_amount" value="<?= $escape($opportunity['value_amount']) ?>" required></label><label>Expected close<input type="date" name="expected_close_on" value="<?= $escape($opportunity['expected_close_on']??'') ?>"></label><button>Save details</button></form></section><section><h2>Advance stage</h2><?php if($allowed===[]):?><p>No further transitions.</p><?php else:?><form method="post" action="<?= $escape($transitionUrl) ?>"><input type="hidden" name="_csrf" value="<?= $escape($csrfToken) ?>"><input type="hidden" name="version" value="<?= $escape($opportunity['version']) ?>"><label>New stage<select name="to_stage"><?php foreach($allowed as $stage):?><option value="<?= $escape($stage) ?>"><?= $escape($stages[$stage]) ?></option><?php endforeach;?></select></label><label>Reason / loss reason<textarea name="reason"></textarea></label><label>When closing, handle the open next action<select name="follow_up_disposition"><option value="retain">Keep as prospect follow-up</option><option value="complete">Complete it</option><option value="cancel">Cancel it</option></select></label><button>Update stage</button></form><?php endif;?></section><?php else:?><section><h2>Close outcome</h2><p>Closed <?= $escape($opportunity['closed_at']) ?><?= $opportunity['lost_reason']?' — '.$escape($opportunity['lost_reason']):'' ?></p></section><?php endif;?><section><h2>Stage history</h2><ol class="timeline"><?php foreach($events as $event):?><li><strong><?= $escape($stages[$event['to_stage']]??$event['to_stage']) ?></strong> <time><?= $escape($event['occurred_at']) ?></time><?= $event['reason']?' — '.$escape($event['reason']):'' ?></li><?php endforeach;?></ol></section>
